  "code": "def generated_loss(batch, model_output, extra):\n    margin = extra.get('margin', 1.0)\n    log_prob_w = model_output['log_prob_w']\n    log_prob_l = model_output['log_prob_l']\n    weight = model_output['weight']\n    cost_gap = batch.get('cost_gap', ops.zeros_like(log_prob_w))\n    # Compute pairwise difference\n    diff = cost_gap + margin\n    # Compute pairwise hinge loss\n    hinge = ops.maximum(ops.zeros_like(diff), diff)\n    # Compute scaled probabilities\n    prob_scale = ops.exp(log_prob_w - log_prob_l)\n    loss_matrix = hinge * prob_scale * weight\n    # Aggregate mean loss\n    loss = ops.mean(loss_matrix)\n    return loss"
}

