  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_gap = batch['advantage_gap']\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    x = scale * adv_gap * (lpw - lpl)\n    prob = ops.sigmoid(x)\n    eps = 1e-8\n    loss = -ops.log(prob + eps)\n    if weight is not None:\n        weighted_loss = loss * weight\n        return weighted_loss.sum() / (weight.sum() + eps)\n    else:\n        return loss.mean()"
