{
  "name": "loss_logsigmoid_000_cost_advantage",
  "intuition": "This loss stabilizes training by combining the pairwise log-probability margin with the advantage gap, providing a richer quality signal. The margin is scaled and shifted by the advantage difference, which captures relative improvements between winning and losing samples, enhancing model discrimination. Clamping the combined margin to [-20,20] ensures numerical stability by preventing extreme inputs to the logsigmoid, which could cause gradient issues. Weighting supports per-sample importance, and mean aggregation produces a smooth scalar loss.",
  "generated_loss": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.5))\n    gap = (adv_l - adv_w).detach()\n    x = alpha * scale * (lpw - lpl) - 0.1 * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()",
