{
  "name": "loss_pairwise_ranknet_advantage_weighted",
  "intuition": "A RankNet-inspired pairwise logistic loss using advantage signals as adaptive weights to emphasize pairs with higher relative quality difference, shifting from margin-based to probabilistic ranking paradigm.",
  "pseudocode": "prob = sigmoid(lpw - lpl)\nweight_adj = 1 + abs(advantage_w - advantage_l)\nloss = -weight * weight_adj * (advantage_w > advantage_l) * log(prob) - weight * weight_adj * (advantage_w <= advantage_l) * log(1 - prob)\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_probabilistic",
    "signal_family": "advantage_gap",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["sigmoid", "log", "abs", "mul", "sub", "mean", "where"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', 1.0)\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    prob = ops.sigmoid(lpw - lpl)\n    advantage_diff = advantage_w - advantage_l\n    weight_adj = 1 + ops.abs(advantage_diff)\n    # Indicator for winner advantage greater than loser\n    indicator = ops.where(advantage_diff > 0, 1.0, 0.0)\n    loss_pos = -weight * weight_adj * indicator * ops.log(prob + 1e-12)\n    loss_neg = -weight * weight_adj * (1.0 - indicator) * ops.log(1.0 - prob + 1e-12)\n    loss = loss_pos + loss_neg\n    return loss.mean()"
}

